import{_ as r,c as a,o,a5 as i}from"./chunks/framework.CUJoMJm2.js";const m=JSON.parse('{"title":"SBP Behavior & Ordering (v1)","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/sbp/behavior.md","filePath":"protocols/sbp/behavior.md","lastUpdated":1768070912000}'),t={name:"protocols/sbp/behavior.md"};function s(n,e,l,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/sbp/behavior.md for this page in Markdown format</div><h1 id="sbp-behavior-ordering-v1" tabindex="-1">SBP Behavior &amp; Ordering (v1) <a class="header-anchor" href="#sbp-behavior-ordering-v1" aria-label="Permalink to “SBP Behavior &amp; Ordering (v1)”">​</a></h1><blockquote><p><strong>Authority</strong>: Primary (Normative)<br><strong>Purpose</strong>: Runtime semantics, ordering guarantees, and delivery expectations for SBP.</p></blockquote><p>Semantic guarantees and expectations that sit above the raw frame format. Applies across transports; transport-specific notes call out deviations.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to “Lifecycle”">​</a></h2><ul><li>Handshake first: each peer MUST send a Handshake control frame before any Message/Ack/Error. Receiving non-handshake frames before handshake → <code>ProtocolViolation</code> then close.</li><li>Liveness: peers MAY send <code>Ping</code>; receivers SHOULD respond with <code>Pong</code> promptly. Unanswered pings can drive transport-level timeouts.</li><li>Close: either side MAY send <code>Control:Close</code> and then terminate the transport.</li></ul><h2 id="ordering-and-delivery" tabindex="-1">Ordering and delivery <a class="header-anchor" href="#ordering-and-delivery" aria-label="Permalink to “Ordering and delivery”">​</a></h2><ul><li>Within a single transport stream (WebSocket or loopback), frames are delivered in send order (reliable, ordered). Transports must preserve order.</li><li>No cross-stream ordering: when multiple transports are used concurrently, ordering is per-transport only.</li><li>Duplicate tolerance: the protocol does not promise global exactly-once. Implementations MAY resend on reconnect; consumers SHOULD treat <code>Message</code> with the same <code>id</code> as idempotent or deduplicate at a higher layer.</li><li>Ack semantics: <code>Ack.ackId</code> confirms receipt (not processing) of the frame whose <code>id</code> matches <code>ackId</code>. No cumulative or windowed ACKs defined in v1.</li><li>Timestamp: informational; does not affect ordering or validity.</li></ul><h2 id="delivery-expectations-by-transport" tabindex="-1">Delivery expectations by transport <a class="header-anchor" href="#delivery-expectations-by-transport" aria-label="Permalink to “Delivery expectations by transport”">​</a></h2><ul><li>Browser WS: ordered, reliable delivery; disconnects may drop in-flight frames. No backpressure signals beyond close/error.</li><li>Node/Bun WS: same as browser; server implementations SHOULD cap message size and enforce idle timeouts.</li><li>Memory/loopback: ordered, reliable; optional loss simulation MUST be documented by the implementation.</li></ul><h2 id="state-and-idempotency" tabindex="-1">State and idempotency <a class="header-anchor" href="#state-and-idempotency" aria-label="Permalink to “State and idempotency”">​</a></h2><ul><li>Requests/responses/events share the <code>Message</code> frame; correlation (<code>id</code>) is the only built-in state tracker.</li><li>Consumers SHOULD make request handlers idempotent per <code>id</code> when possible; retries may occur after transport drops.</li><li>Acks are advisory; higher layers decide whether to retry or treat missing ACKs as failures.</li></ul><h2 id="security-and-safety" tabindex="-1">Security and safety <a class="header-anchor" href="#security-and-safety" aria-label="Permalink to “Security and safety”">​</a></h2><ul><li>Size limits: peers SHOULD enforce max frame size (see wire spec) and reject oversize frames with <code>ProtocolViolation</code>.</li><li>Rate limits: implementations MAY throttle handshakes/pings/error floods; exceeding limits SHOULD close the transport.</li><li>Integrity: no built-in MAC; rely on transport security (TLS) and higher-layer auth. Do not trust <code>peerId</code> without external verification.</li><li>Cross-origin (browser): host apps must configure allowed origins and reject unauthorized WS upgrades; protocol itself is origin-agnostic.</li></ul><h2 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to “Observability”">​</a></h2><ul><li>Errors: prefer sending <code>ErrorFrame</code> before closing when feasible; log both <code>code</code> and <code>message</code>.</li><li>Metrics: count frames by type, error codes, ping/pong latency, handshake failures.</li></ul>',16)])])}const u=r(t,[["render",s]]);export{m as __pageData,u as default};
